    /* A declaration's parameter types without self, as the trait or object being checked
     * has them, over the method's own static parameters renamed apart (ownStaticParamsApart):
     * what STypesUtil.providedMethods compares. */
    private def paramsWithoutSelf(d: (JavaFunctional, StaticTypeReplacer, TraitType)): Option[Type] = d match {
      case (f, replacer, _) =>
        val ps = toListFromImmutable(f.parameters)
        val kept = f match {
          case m: JavaFunctionalMethod => ps.zipWithIndex.filter(_._2 != m.selfPosition).map(_._1)
          case _ => ps }
        STypesUtil.paramsToType(kept, f.getSpan).map { t =>
          val (sparams, apart) = ownStaticParamsApart(f)
          replacer.replaceIn(insertStaticParams(apart(t), sparams)) }
    }

    // for dotted methods
    private def toMethodArrows(set: Set[(JavaFunctional, StaticTypeReplacer, TraitType)])
                           : List[(ArrowType,Option[Int],Option[JavaFunctional])] =
      set.filter(p => p match { case (f, _, _) => isDeclaredMethod(f)})
         .toList.map(p => p match { case (f, replacer, _) =>
              val (sparams, apart) = ownStaticParamsApart(f)
              (NF.makeArrowType(f.getSpan,
	                        replacer.replaceIn(apart(paramsToType(f.asInstanceOf[JavaMethod].selfType.unwrap, f.parameters, f.getSpan))),
                		replacer.replaceIn(apart(f.getReturnType.unwrap)),
				sparams),
               None,
	       Some(f))})

    // a getter, as toMethodArrows reads a dotted method, its receiver its one parameter; the
    // receiver is the plain type that declares it, at the instance that the checked type
    // reaches, as the Return Type Rule reads a self-typed trait's signature (traits.tex,
    // "Method Declarations"), not the self type that its bodies read
    private def getterArrow(d: (JavaFunctional, StaticTypeReplacer, TraitType))
                           : Option[(ArrowType,Option[Int],Option[JavaFunctional])] = d match {
      case (f: JavaMethod, replacer, owner) if f.getReturnType.isSome =>
        Some((NF.makeArrowType(f.getSpan,
                               paramsToType(owner, f.parameters, f.getSpan),
                               replacer.replaceIn(f.getReturnType.unwrap),
                               getStaticParameters(f, false)),
              None,
              Some(f)))
      case _ => None
    }

    /* An inherited method's own static parameters, each whose name is a static parameter
     * of the trait or object being checked renamed apart, so that the arguments the
     * replacer puts in place of the declaring trait's parameters are not captured. */
    private def ownStaticParamsApart(f: JavaFunctional): (JavaList[StaticParam], Type => Type) = {
      val own = toListFromImmutable(getStaticParameters(f, false))
      val env = typeAnalyzer.env
      val taken = own.map(_.getName.getText).toSet
      val clash = own.filter(p => env.contains(p.getName))
      if (clash.isEmpty) return (getStaticParameters(f, false), (t: Type) => t)
      val subst: List[(IdOrOp, IdOrOp)] = clash.map { p =>
        val n = p.getName
        val fresh = Iterator.from(1).map(i => NF.makeId(NU.getSpan(n), n.getText + "$" + i))
                            .find(m => !env.contains(m) && !taken.contains(m.getText)).get
        (n, fresh) }
      def apart(t: Type): Type = alphaRename(subst, t).asInstanceOf[Type]
      // every own parameter's bounds are renamed, so that a bound naming a renamed parameter names it still
      val renamed = own.map(p => {
        def bounds = toJavaList(toListFromImmutable(p.getExtendsClause).map(b => alphaRename(subst, b).asInstanceOf[BaseType]))
        subst.find(_._1 == p.getName) match {
          case Some((_, m)) => NF.makeStaticParam(p, m.asInstanceOf[Id], bounds)
          case None => p.getName match {
            case n: Id if !p.getExtendsClause.isEmpty => NF.makeStaticParam(p, n, bounds)
            case _ => p }
        } })
      (toJavaList(renamed), apart)

      else {
        val hs = signatures.collect {
          case (ha, hsp, _) if hsp == fsp && !(ha eq fa) && !(ha eq ga) &&
                               oa.lteq(ha, fa) && oa.lteq(ha, ga) => ha }
        if (isMethod) {
          val i = fsp.get
          oa.coversOverlap(withoutSelf(fa, i), withoutSelf(ga, i), hs.map(withoutSelf(_, i)))
        }
        else oa.coversOverlap(fa, ga, hs)
      }
    }

    /* The return types of a declaration o and of a declaration p that it keeps the type
     * declaring it from inheriting (STypesUtil.providedAndOverridden). Where their parameter
     * types are the same, the two are checked as the pair of an overloading was, o being the
     * more specific, two getters among them (overloading.tex, "Declarations with Static
     * Parameters", the Return Type Rule); where o has the modifier override and widens p's,
     * o's return type must be a subtype of p's (traits.tex, "Method Declarations"): with static
     * parameters, at every instance of p, and where both declare as many of their own, also
     * position by position. */
    private def checkOverridingReturnType(name: IdOrOpOrAnonymousName,
                                          o: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          p: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          equal: Boolean,
                                          oracle: OverloadingOracle): Unit = {
      val getters = isGetter(o._1) && isGetter(p._1)
      def arrow(d: (JavaFunctional, StaticTypeReplacer, TraitType)) =
        if (isFunctionalMethod(d._1)) toFunctionalMethodArrows(Set(d), oracle).headOption
        else if (getters) getterArrow(d)
        else toMethodArrows(Set(d)).headOption
      (arrow(o), arrow(p)) match {
        case (Some(oa), Some(pa)) =>
          if (equal) {
            returnTypeCheck(name, oa, pa, oracle)
            returnTypeCheck(name, pa, oa, oracle)
          } else {
            def own(a: ArrowType) = toListFromImmutable(a.getInfo.getStaticParams).filter(!_.isLifted)
            // the self parameter, or a dotted method's receiver, apart
            val at = oa._2.getOrElse(0)
            val holds =
              if (own(oa._1).isEmpty && own(pa._1).isEmpty)
                isTrue(typeAnalyzer.subtype(oa._1.getRange, pa._1.getRange))(typeAnalyzer)
              else oracle.sa.subtypeUA(withoutSelf(oa._1, at), withoutSelf(pa._1, at)) &&
                   oracle.satisfiesPositionalRule(oa._1, pa._1)
            if (!holds)
              error(mergeSpan(oa._1, pa._1),
                    "For " + name + ",\nthe return type of the overriding declaration " + typeAndSpanToString(oa._1) +
                    " should be a subtype of the\n    return type of the declaration it overrides " + typeAndSpanToString(pa._1))
          }
        case _ =>
      }
    }

    private def returnTypeCheck(name: IdOrOpOrAnonymousName,
    	    			first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                second: (ArrowType,Option[Int],Option[JavaFunctional]),
			        oa: OverloadingOracle) = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
//          println("Satisfies return type rule?\n   " + typeAndSpanToString(fa) + "\n   " + typeAndSpanToString(ga))
      if (!oa.satisfiesReturnTypeRule(fa, ga)) {
//        println("For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
        error(mergeSpan(fa, ga),
	      "For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
      }
      else if (oa.lteq(fa, ga) && !oa.satisfiesPositionalRule(fa, ga))
        error(mergeSpan(fa, ga),
              "For " + name + ",\nthe static parameters of " + typeAndSpanToString(fa) + " should correspond position by position\n    to those of " + typeAndSpanToString(ga) +
              ":\n    of the same kinds, with a return type that is a subtype of the other's under that correspondence.")
    }


    /* Drop the first element denoting the receiver type of the given type. */
    private def dropReceiver(param: Type) = param match {
      case STupleType(info, _::ty::Nil, None, Nil) => ty
      case STupleType(info, elements, varargs, keywords) =>
        STupleType(info, elements.takeRight(elements.size-1), varargs, keywords)
      case _ => NodeFactory.makeVoidType(NU.getSpan(param))
    }

    def isDeclaredName(f: IdOrOpOrAnonymousName) = f match {
        case SId(_,_,str) => IdentifierUtil.validId(str)
        case SOp(_,_,str,_,_) => NU.validOp(str)
        case _ => false
    }

    // the names whose declarations the overloading rules are checked for: every operator,
    // symbolic ones such as + and the subscripts as well as those named by a word of
    // capitals, and each identifier that isDeclaredName admits (overloading.tex,
    // "Principles of Overloading"); the export check reads it too, with isDeclarationName
    def isCheckedName(f: IdOrOpOrAnonymousName) = f match {
        case SOp(_,_,_,_,_) => true
        case _ => isDeclaredName(f)
    }

    def isDeclaredMethod(f: JavaFunctional) = f match {
        case SDeclaredMethod(_,_) => true
        case _ => false
    }

    def isGetter(f: JavaFunctional) = f match {
        case SFieldGetterMethod(_,_) => true
        case _ => false
    }

    def isFunction(f: JavaFunctional) = f match {
        case SDeclaredFunction(_) => true
        case SFunctionalMethod(_,_) => true
        case SConstructor(_,_,_,_,_) => true
        case _ => false
    }

